sys_script_email.script:
// Notification Email Script name: clm_request_step_approved
// Notification table: x_birl3_clm_clm_new_credit_request
(function runMailScript(current, template, email, email_action, event) {

    function esc(s) { return GlideStringUtil.escapeHTML(s || ''); }
    function inr(n) {
        var s = Math.round(Math.abs(n)).toString();
        var last = s.slice(-3), rest = s.slice(0, -3);
        if (rest) last = rest.replace(/\B(?=(\d{2})+(?!\d))/g, ',') + ',' + last;
        return last;
    }
    function rupee(n) { return '&#8377; ' + inr(n); }

    // ── Event parms ────────────────────────────────────────────────
    // parm1 = approver name who just approved
    // parm2 = approver role (label from the chain)
    // parm3 = next approver role (label)
    // parm4 = next approver name
    // parm5 = approved limit (raw number, may be empty)
    // parm6 = comments (may be empty)
   var approvedBy = (event && event.parm1) ? event.parm1 + '' : '';

var info = {};
try { info = JSON.parse((event && event.parm2) ? event.parm2 + '' : '{}'); } catch (e) { info = {}; }

var approvedByRole   = info.role      || '';
var nextRole         = info.next_role || '';
var nextName         = info.next_name || '';
var approvedLimitRaw = info.limit ? info.limit + '' : '';
var comments         = info.comments  || '';

var approvedLimit = parseFloat(approvedLimitRaw) || 0;

    // ── Request + customer context ─────────────────────────────────
    var reqNumber    = current.getValue('number') + '';
    var customerName = '';
    var customerCode = '';
    var pan          = '';
    var isTrade      = ((current.getValue('customer_type') || '') + '').toLowerCase() === 'trade';
    var requestedLimit = isTrade
        ? (parseFloat(current.getValue('u_code_level_total_requested')) || 0)
        : (parseFloat(current.getValue('requested_limit')) || 0);
    var currentLimit = parseFloat(current.getValue('u_code_level_current_limit')) || 0;

    var custSysId = current.getValue('customer') + '';
    if (custSysId) {
        var custGR = new GlideRecord('x_birl3_clm_clm_customer_master1');
        if (custGR.get(custSysId)) {
            customerName = custGR.getValue('customer_name') + '';
            customerCode = custGR.getValue('customer_code_sap') + '';
            pan          = custGR.getValue('pan') + '';
        }
    }

    var base = (gs.getProperty('glide.servlet.uri') || '').replace(/\/?$/, '/');
    var link = base + 'uclm?id=view_my_credit_request';

    // ── Styles ─────────────────────────────────────────────────────
    var TD_K = 'padding:8px 0; color:#5a6a7a; border-bottom:1px solid #eef1f5;';
    var TD_V = 'padding:8px 0; color:#1a1a1a; border-bottom:1px solid #eef1f5;';
    var TILE = 'border:1px solid #e0e6ed; border-radius:6px; padding:12px 14px; background-color:#fafbfc;';
    var TILE_K = 'font-size:10px; text-transform:uppercase; letter-spacing:.8px; color:#5a6a7a; font-weight:700;';

    function sec(t, top) {
        return '<h3 style="margin:' + (top || 24) + 'px 0 8px 0; font-size:13px; text-transform:uppercase; letter-spacing:1px; color:#1a1a1a; border-bottom:2px solid #F3D54E; padding-bottom:6px;">' + t + '</h3>';
    }
    function kv(label, value, last, bold) {
        return '<tr><td width="38%" style="' + (last ? 'padding:8px 0; color:#5a6a7a;' : TD_K) + '">' + label + '</td>' +
               '<td style="' + (last ? 'padding:8px 0; color:#1a1a1a;' : TD_V) + (bold ? ' font-weight:700;' : '') + '">' + value + '</td></tr>';
    }

    var h = '';

    // ── Progress banner (blue/informational, not green) ────────────
    h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#f4f9fb; border:1px solid #aed6f1; border-left:5px solid #3498db; border-radius:6px; margin-top:6px;"><tbody><tr>';
    h += '<td width="52" align="center" valign="middle" style="padding:16px 0 16px 14px;"><div style="width:36px; height:36px; line-height:36px; border-radius:18px; background-color:#3498db; color:#ffffff; font-size:20px; font-weight:700; text-align:center;">&#8594;</div></td>';
    h += '<td style="padding:16px 16px 16px 12px;"><div style="font-size:20px; font-weight:700; color:#1a5276;">Request moved to the next approver</div>';
    h += '<div style="font-size:13px; color:#3a4451; padding-top:2px;">' + (approvedBy ? esc(approvedBy) + (approvedByRole ? ' (' + esc(approvedByRole) + ')' : '') + ' approved' : 'Approved') + (nextRole ? ' &middot; now awaiting ' + esc(nextRole) : '') + '</div></td>';
    h += '</tr></tbody></table>';

    // ── Request number card ────────────────────────────────────────
    h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin-top:16px; background-color:#fffcf0; border:1px solid #F3D54E; border-radius:6px;"><tbody><tr>';
    h += '<td style="padding:12px 16px;"><div style="font-size:11px; text-transform:uppercase; letter-spacing:1px; color:#5a6a7a; font-weight:700;">Request Number</div>';
    h += '<div style="font-size:18px; font-weight:700; color:#1a1a1a;">' + esc(reqNumber) + '</div>';
    h += '<div style="font-size:12px; color:#5a6a7a; padding-top:2px;">Submitted on ' + esc(current.getDisplayValue('sys_created_on')) + '</div></td>';
    h += '<td align="right" valign="middle" style="padding:12px 16px;"><span style="display:inline-block; background-color:#eaf4fb; color:#1a5276; border:1px solid #aed6f1; border-radius:4px; padding:5px 12px; font-size:11px; font-weight:700; letter-spacing:.5px; text-transform:uppercase;">In Progress</span></td>';
    h += '</tr></tbody></table>';

    // ── Who approved / who is next ─────────────────────────────────
    h += sec('Approval Progress', 24);
    h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#fafbfc; border:1px solid #e0e6ed; border-radius:6px;"><tbody>';
    h += '<tr><td style="padding:14px 18px;">';
    h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="font-size:14px;"><tbody>';

    // Approved by row
    h += '<tr><td width="40%" style="padding:6px 0; color:#5a6a7a; font-weight:600;">Approved By</td>';
    h += '<td style="padding:6px 0; color:#1a1a1a; font-weight:700;">' + (approvedBy ? esc(approvedBy) : '—');
    if (approvedByRole) h += ' <span style="color:#8a96a3; font-weight:400;">(' + esc(approvedByRole) + ')</span>';
    h += '</td></tr>';

    // Next approver row
    h += '<tr><td width="40%" style="padding:6px 0; color:#5a6a7a; font-weight:600;">Now With</td>';
    h += '<td style="padding:6px 0; color:#1a5276; font-weight:700;">' + (nextRole ? esc(nextRole) : '—');
    if (nextName) h += ' <span style="color:#8a96a3; font-weight:400;">&middot; ' + esc(nextName) + '</span>';
    h += '</td></tr>';

    h += '</tbody></table>';
    h += '</td></tr></tbody></table>';

    // ── Limits tiles ──────────────────────────────────────────────
    h += sec('Credit Limit', 24);
    h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tbody><tr>';
    if (isTrade) {
        h += '<td width="50%" valign="top" style="padding-right:6px;"><div style="' + TILE + '"><div style="' + TILE_K + '">Current Limit</div><div style="font-size:17px; font-weight:700; padding-top:3px;">' + rupee(currentLimit) + '</div></div></td>';
        h += '<td width="50%" valign="top" style="padding-left:6px;"><div style="' + TILE + '"><div style="' + TILE_K + '">Requested</div><div style="font-size:17px; font-weight:700; padding-top:3px;">' + rupee(requestedLimit) + '</div></div></td>';
    } else {
        h += '<td width="100%" valign="top"><div style="' + TILE + '"><div style="' + TILE_K + '">Requested Limit</div><div style="font-size:17px; font-weight:700; padding-top:3px;">' + rupee(requestedLimit) + '</div></div></td>';
    }
    h += '</tr></tbody></table>';

    // If this approver recommended a specific limit (override), show it
    if (approvedLimit && approvedLimit !== requestedLimit) {
        h += '<p style="margin:10px 0 0 0; padding:10px 14px; background-color:#fffcf0; border:1px solid #F9E79F; border-radius:6px; font-size:13px; color:#8a6100;">This approver recommended a limit of <strong>' + rupee(approvedLimit) + '</strong> for this step.</p>';
    }

    // ── Comments ──────────────────────────────────────────────────
    if (comments) {
        h += sec('Approver Comments', 24);
        h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#f4f9fb; border-left:4px solid #3498db;"><tbody><tr><td style="padding:12px 16px;">';
        h += '<div style="font-size:13.5px; line-height:1.6; color:#1a1a1a; white-space:pre-line; word-wrap:break-word;">' + esc(comments) + '</div>';
        h += '</td></tr></tbody></table>';
    }

    // ── Request summary ───────────────────────────────────────────
    h += sec('Request Summary');
    h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="font-size:14px;"><tbody>';
    h += kv('Customer Name', esc(customerName || '—'), false, true);
    h += kv('Customer Code', esc(customerCode || '—'));
    if (pan) h += kv('PAN', esc(pan));
    h += kv('Customer Type', esc(current.getDisplayValue('customer_type')));
    h += kv('Segment', esc(current.getDisplayValue('segment')), true);
    h += '</tbody></table>';

    // ── What happens next ─────────────────────────────────────────
    h += sec('What Happens Next');
    h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#f4f9fb; border-left:4px solid #3498db;"><tbody><tr><td style="padding:12px 16px; font-size:13px; line-height:1.6; color:#1a1a1a;">';
    h += 'The request is now pending with <strong>' + (nextRole ? esc(nextRole) : 'the next approver') + '</strong>' + (nextName ? ' (' + esc(nextName) + ')' : '') + '. No action is required from you right now — you&rsquo;ll be notified at each step until the request is fully approved or rejected.';
    h += '</td></tr></tbody></table>';

    // ── CTA ───────────────────────────────────────────────────────
    h += '<table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin-top:28px;"><tbody><tr>';
    h += '<td align="center" style="background-color:#1a1a1a; border-radius:6px; border-bottom:3px solid #F3D54E;">';
    h += '<a href="' + link + '" style="display:inline-block; padding:12px 28px; font-size:13px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; color:#ffffff; text-decoration:none;">View Request in CredX</a>';
    h += '</td></tr></tbody></table>';

    h += '<p style="margin:14px 0 0 0; font-size:12px; color:#8a96a3;">Open the request in CredX to see the complete approval trail.</p>';

    template.print(h);

})(current, template, email, email_action, event);
